<?php
namespace App\Controllers;use App\Core\Database;use App\Core\Security;use App\Core\Auth;
final class AcquisitionController{public function index():void{Auth::requireRole(['administrator','librarian']);$db=Database::connection();$db->exec('CREATE TABLE IF NOT EXISTS acquisitions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,supplier VARCHAR(180),quantity INT UNSIGNED NOT NULL,unit_cost DECIMAL(10,2) DEFAULT 0,acquired_at DATE NOT NULL,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_acq_book FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE) ENGINE=InnoDB');$rows=$db->query('SELECT a.*,b.title FROM acquisitions a JOIN books b ON b.id=a.book_id ORDER BY a.acquired_at DESC')->fetchAll();$title='Book Acquisitions';require BASE_PATH.'/app/Views/acquisitions/index.php';}public function create():void{Auth::requireRole(['administrator','librarian']);$db=Database::connection();$books=$db->query('SELECT id,title FROM books ORDER BY title')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'&&Security::validCsrf($_POST['_csrf']??null)){$db->beginTransaction();$s=$db->prepare('INSERT INTO acquisitions(book_id,supplier,quantity,unit_cost,acquired_at,notes) VALUES(?,?,?,?,?,?)');$s->execute([(int)$_POST['book_id'],trim($_POST['supplier']),max(1,(int)$_POST['quantity']),$_POST['unit_cost']?:0,$_POST['acquired_at'],trim($_POST['notes']??'')]);$db->prepare('UPDATE books SET quantity=quantity+?,available_quantity=available_quantity+? WHERE id=?')->execute([(int)$_POST['quantity'],(int)$_POST['quantity'],(int)$_POST['book_id']]);$db->commit();Security::flash('success','Acquisition saved and stock updated.');Security::redirect('acquisitions');}$title='Record Acquisition';require BASE_PATH.'/app/Views/acquisitions/form.php';}public function delete():void{Auth::requireRole(['administrator','librarian']);if(!Security::validCsrf($_POST['_csrf']??null)){Security::flash('danger','Request expired.');Security::redirect('acquisitions');}Database::connection()->prepare('DELETE FROM acquisitions WHERE id=?')->execute([(int)$_POST['id']]);Security::flash('success','Acquisition record deleted. Inventory quantities were not changed.');Security::redirect('acquisitions');}}
